function e(e){if(e<0||Number.isNaN(e))return`—`;let t=1024;if(e<t)return`${e.toFixed(0)} B`;let n=t,r=0;for(let i=e/t;i>=t;i/=t)n*=t,r++;return`${(e/n).toFixed(1)} ${`KMGTPE`[r]}B`}function t(e){let t=new Date(e);if(Number.isNaN(t.getTime()))return`—`;let n=e=>String(e).padStart(2,`0`);return`${t.getFullYear()}-${n(t.getMonth()+1)}-${n(t.getDate())} ${n(t.getHours())}:${n(t.getMinutes())}`}export{t as n,e as t};